//angular = require 'angular'

const module = angular.module("irtech.netcity.school.attestation",
[
	"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap", "ngFileUpload", "ui.tree",
	"irtech.netcity.common", "irtech.netcity.ui-components"
]);
require("./list/attestListCtrl.js");
require("./portfolio/staffPortfolioCtrl.js");

module.directive("nsDateModel", () => {
	const toStr = function (dateParam) {
		return dateParam ? dateUtils.date2strfrm(new Date(dateParam), `dd${String.fromCharCode(1)}mm${String.fromCharCode(1)}yyyy${String.fromCharCode(1)}.`) : null;
	}
	return {
		restrict: 'A',
		scope: {
			date: "=nsDateModel"
		},
		link: (scope, element) => {
			let isoDate = scope.date;
			let strDate = toStr(isoDate);

			$(element).val(strDate);

			$(element).change(() => {
				let date = dateUtils.str2date($(element).val());
				if (date) {
					scope.date = date.toISOString();
				} else {
					scope.date = null;
				}
				scope.$apply();
			});
		},
		replace: false
	}
})
.config(($routeProvider, $locationProvider) => {
	$routeProvider
		.when("/list", {
			templateUrl: "/static/dist/app/school/attestation/list/template.html",
			controller: "ListAttestationCtrl"
		})
		.when("/portfolio/:userId?", {
			templateUrl: "/static/dist/app/school/attestation/portfolio/template.html",
			controller: "PortfolioAttestationCtrl"
		})
		.otherwise({
			redirectTo: "/list"
		});
	$locationProvider.hashPrefix('');
	$locationProvider.html5Mode({
		enabled: true,
		requireBase: true
	});
});



