					$http.get(`/webapi/refs/staff/portfolio/fileCategories`).then((response) => $scope.refs.fileCategories = response.data),
					$http.get(`/webapi/refs/staff/portfolio/retrainingTypes`).then((response) => $scope.refs.retrainingTypes = response.data),
					$http.get(`/webapi/refs/staff/portfolio/participationStatus`).then((response) => $scope.refs.participationStatus = response.data),
					$http.get(`/webapi/refs/staff/portfolio/educDocumentType`).then((response) => {
						$scope.refs.educDocTypes = response.data;
						$scope.refs.educDocTypes.index = _.indexBy(response.data, "key");
					})
