"use strict";

angular
	.module("irtech.netcity.school.attestation")
	.controller("ListAttestationCtrl", ($scope, $http, $document, $location, $appLoader) => {

		$scope.$parent.page = {
			title: language.Generic.MenuFolders.kStaffAttestMyAttestation
		}

		$scope.userId = appContext.userId;
		
		$.extend($scope, {
			data: {
				language: language,
				staffAttestUrl: "",
				attestations: []
			},
			state: {
				dataReady: false,
				emptyData: false
			},
			ready: false
		});

		$scope.dateOnly2strF = function (dateParam) {
			return dateParam ? dateUtils.date2strfrm(new Date(dateParam), `dd${String.fromCharCode(1)}mm${String.fromCharCode(1)}yyyy${String.fromCharCode(1)}.`) : null;
		}

		$scope.openStaffAttestModule = function (url) {
			openPopupWindow("_staffAttest", url, 1024, 800);
		}

		$scope.openStaffAttestModuleNewRequest = function () {
			$scope.openStaffAttestModule(`/webapi/integration/staffattest/newrequest`);
		}

		$scope.openStaffAttestModuleEditRequest = function (id) {
			$scope.openStaffAttestModule(`/webapi/integration/staffattest/editrequest?id=${id}`);
		}

		//загрузка данных
		$scope.load = () => {
			$http.get(`/webapi/users/${$scope.userId}/staff/attest`)
				.then((response) => {
					$scope.data.attestations = response.data;
					$scope.state.dataReady = true;
					$scope.state.emptyData = !response.data.length;
					$scope.ready = true;
					$appLoader.hide();
				})
				.catch((response) => {
					//отображение в темплейте
					$scope.error = response.message || response.details || language.Generic.Common.kUnexpErr;
				});
		}

		$scope.load();
	});



